"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["13398"],{12071(e){e.exports=JSON.parse('{"id":"F195","slug":"commercial-paper-yield","name":"Commercial Paper Price and Yield","subject":"Corporate Finance","section":"Working Capital Management","topic":"Short-term financing: commercial paper, credit lines","level":"Intermediate","aliases":["discount instrument","commercial paper","treasury bill yield","short-term financing"],"formula":{"latex":"P=F\\\\left(1-d\\\\frac{t}{360}\\\\right),\\\\quad Y=\\\\frac{F-P}{P}\\\\times\\\\frac{365}{t}","also":[],"text":"Price = Face x (1 - discount rate x days / 360); Yield = (Face - Price) / Price x 365 / days"},"symbols":[{"symbol":"F","meaning":"Face value paid at maturity","unit":"money"},{"symbol":"d","meaning":"Quoted discount rate, as a decimal","unit":"per year"},{"symbol":"t","meaning":"Days until maturity","unit":"days"},{"symbol":"P","meaning":"Price the investor pays today","unit":"money"},{"symbol":"Y","meaning":"Investor\'s yield, which is also the borrower\'s cost before fees","unit":"per year"}],"when_to_use":"Use it for discount instruments such as commercial paper, which are issued below face value and repaid at face value. The quoted discount rate understates the true cost of borrowing.","worked_example":{"problem":"A company issues 1,000,000 of 90-day commercial paper at a quoted discount rate of 4%. What price does it receive and what is the yield?","inputs":{"f":1000000,"d":4,"t":90},"steps":[{"label":"Discount in money = F x d x t / 360","working":"1,000,000 x 0.04 x 90 / 360","value":"10,000.00"},{"label":"Price = F - discount","working":"1,000,000-10000","value":"990,000.00"},{"label":"Yield = (F - P) / P x 365 / t","working":"(1,000,000-990000) / 990000 x 365 / 90","value":"4.10%"}],"answer":"The paper sells for 990,000.00. The company pays back 1,000,000, so the true yield is 4.10%, above the quoted 4%."},"calculator":{"available":true,"inputs":[{"id":"f","label":"Face value","unit":"money","type":"number","default":1000000,"hint":""},{"id":"d","label":"Quoted discount rate","unit":"%","type":"number","default":4,"hint":""},{"id":"t","label":"Days to maturity","unit":"days","type":"number","default":90,"hint":""}],"checks":[{"expr":"t>0","message":"The days to maturity must be above zero."}],"steps":[{"id":"disc","label":"Discount in money = F x d x t / 360","expr":"f*d*t/360","format":"money"},{"id":"p","label":"Price = F - discount","expr":"f-disc","format":"money"},{"id":"y","label":"Yield = (F - P) / P x 365 / t","expr":"(f-p)/p*365/t","format":"pct2"}],"results":["p","y"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"p":990000,"y":4.0965207631874306e-2}},"finder":{"finds":"Price and true yield of short-term paper","needs":"Face value, discount rate, days"},"related":[{"slug":"ear","name":"Effective Annual Rate (EAR)"},{"slug":"annualized-hpr","name":"Annualizing a Holding Period Return"}],"related_ids":["F024","F025"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>P</mi><mo>=</mo><mi>F</mi><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>d</mi><mfrac><mi>t</mi><mn>360</mn></mfrac><mo fence=\\"true\\">)</mo></mrow><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>Y</mi><mo>=</mo><mfrac><mrow><mi>F</mi><mo>\u2212</mo><mi>P</mi></mrow><mi>P</mi></mfrac><mo>\xd7</mo><mfrac><mn>365</mn><mi>t</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">P=F\\\\left(1-d\\\\frac{t}{360}\\\\right),\\\\quad Y=\\\\frac{F-P}{P}\\\\times\\\\frac{365}{t}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"combined-ratio","name":"Combined Ratio (Insurers)"},"next":{"slug":"commodity-roll-yield","name":"Commodity Futures: Basis and Roll Yield"},"lesson":null,"total":522}')}}]);